    } else {
      let tx1 = (minX - oldX) / dx;
      let tx2 = (maxX - oldX) / dx;
      tMin = Math.max(tMin, Math.min(tx1, tx2));
      tMax = Math.min(tMax, Math.max(tx1, tx2));
    }

    if (dy === 0) {
      if (oldY < minY || oldY > maxY) continue;
    } else {
