    state.combo = 0; // touching the paddle resets the combo
  }

  // Brick collisions (Sweep to prevent tunnelling)
  let firstT = 1.0;
  let firstBrick = null;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Check if the ball's path intersects the brick's expanded bounds
    const minX = brick.x - ball.r;
    const maxX = brick.x + brick.w + ball.r;
    const minY = brick.y - ball.r;
    const maxY = brick.y + brick.h + ball.r;

    const dx = ball.x - oldX;
    const dy = ball.y - oldY;

    let tMin = 0;
    let tMax = 1;

    if (dx === 0) {
      if (oldX < minX || oldX > maxX) continue;
    } else {
      let tx1 = (minX - oldX) / dx;
      let tx2 = (maxX - oldX) / dx;
      tMin = Math.max(tMin, Math.min(tx1, tx2));
      tMax = Math.min(tMax, Math.max(tx1, tx2));
    }

    if (dy === 0) {
      if (oldY < minY || oldY > maxY) continue;
    } else {
      let ty1 = (minY - oldY) / dy;
      let ty2 = (maxY - oldY) / dy;
      tMin = Math.max(tMin, Math.min(ty1, ty2));
      tMax = Math.min(tMax, Math.max(ty1, ty2));
    }

    if (tMax >= tMin && tMin <= 1 && tMax >= 0) {
      const t = tMin < 0 ? 0 : tMin;
      if (t < firstT) {
        firstT = t;
        firstBrick = brick;
      }
    }
  }

  if (firstBrick) {
    const brick = firstBrick;
    // Per-face bounce resolution
    const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

    if (overlapX < overlapY) {
      // Side hit
      ball.vx = -ball.vx;
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    } else if (overlapY < overlapX) {
      // Top/Bottom hit
      ball.vy = -ball.vy;
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    } else {
      // Corner hit
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
      ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

edits.oldText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

